mapper.select:
select id, merchant_id, user_id, create_by, create_time, update_by, update_time
from merchant_users
where merchant_id = #{merchantId} and user_id = #{userId}

select case when count(distinct merchant_id) = 1 then min(merchant_id) else null end
from merchant_users
where user_id = #{userId}

select count(1)
from merchant_users
where merchant_id = #{merchantId}

select count(1)
from merchant_users
where user_id = #{userId}

select u.user_id, u.user_name, u.openid, count(distinct mu.merchant_id) as merchant_count, group_concat(distinct m.name order by m.name separator ', ') as merchant_names, u.create_time, u.update_time, min(mu.create_time) as bind_time from sys_user u join merchant_users mu on mu.user_id = u.user_id join merchants m on m.id = mu.merchant_id
and ( u.user_name like concat('%', #{keyword}, '%') or u.openid like concat('%', #{keyword}, '%') or cast(u.user_id as char) like concat('%', #{keyword}, '%') or m.name like concat('%', #{keyword}, '%') )
group by u.user_id, u.user_name, u.openid, u.create_time, u.update_time order by bind_time desc, u.user_id desc limit #{limit} offset #{offset}
